#include "fedspatial/gpu_context.hpp"
#include "fedspatial/nworker_15k_figure1_config.hpp"
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdlib>
#include <iostream>

using namespace fedspatial;
namespace {
double v(int i,int j){return std::sin(.071*(i+1)*(j+2))+.03*(i-j);}
WorkerInput worker(){constexpr int n=128;Matrix s(n,2),z(n,1),x(n,1);for(int i=0;i<n;++i){s(i,0)=.013*i;s(i,1)=.021*(i%11);z(i,0)=v(i,3);x(i,0)=1.;}return{s,z,x};}
Matrix knots(){constexpr int m=64;Matrix k(m,2);for(int j=0;j<m;++j){k(j,0)=.019*j+.004;k(j,1)=.017*(j%13)+.002;}return k;}
GlobalParameters parameters(){constexpr int m=64;Matrix g(1,1),mu(m,1),sigma(m,m);g(0,0)=.1;for(int i=0;i<m;++i){mu(i,0)=.01*std::cos(.1*i);for(int j=0;j<m;++j)sigma(i,j)=(i==j?.9:0.)+.002*std::exp(-.03*std::abs(i-j));}return{g,mu,sigma,.7,1.15,.43};}
struct Sample{DeviceDeltaThetaMixedHessianReduction result;double ms;};
Sample run(GpuContext& c,const WorkerInput&w,const Matrix&k,const GlobalParameters&p,bool trace,bool contractions){if(trace)setenv("FEDSPATIAL_MIXED_TRACE_TILED_ACTION","1",1);else unsetenv("FEDSPATIAL_MIXED_TRACE_TILED_ACTION");if(contractions)setenv("FEDSPATIAL_MIXED_CONTRACTIONS_TILED","1",1);else unsetenv("FEDSPATIAL_MIXED_CONTRACTIONS_TILED");const auto t0=std::chrono::steady_clock::now();auto r=compute_device_delta_theta_mixed_hessian_reduction_streamed(c,w,k,p);const auto t1=std::chrono::steady_clock::now();return{r,std::chrono::duration<double,std::milli>(t1-t0).count()};}
double diff(const DeviceDeltaThetaMixedHessianReduction&a,const DeviceDeltaThetaMixedHessianReduction&b){double e=0.;for(int i=0;i<2;++i){e=std::max(e,std::abs(a.mixed[i]-b.mixed[i]));for(int j=0;j<5;++j)e=std::max(e,std::abs(a.terms[i][j]-b.terms[i][j]));}return e;}
}
int main(){try{const std::string mask=std::string(NWorker15kFigure1Config::gv100_uuid_0)+","+NWorker15kFigure1Config::gv100_uuid_1;setenv("CUDA_VISIBLE_DEVICES",mask.c_str(),1);const auto w=worker();const auto k=knots();const auto p=parameters();GpuContext c(0);(void)build_device_mu_sigma_local(c,w,k,p);const auto scalar=run(c,w,k,p,false,false);const auto trace=run(c,w,k,p,true,false);const auto all=run(c,w,k,p,true,true);unsetenv("FEDSPATIAL_THETA_FIRST_TILED");const auto t0=std::chrono::steady_clock::now();const auto tf_scalar=compute_device_delta_theta_theta_first_reduction_streamed(c,w,k,p);const auto t1=std::chrono::steady_clock::now();setenv("FEDSPATIAL_THETA_FIRST_TILED","1",1);const auto tf_tiled=compute_device_delta_theta_theta_first_reduction_streamed(c,w,k,p);const auto t2=std::chrono::steady_clock::now();unsetenv("FEDSPATIAL_THETA_FIRST_TILED");const double tf_scalar_ms=std::chrono::duration<double,std::milli>(t1-t0).count(),tf_tiled_ms=std::chrono::duration<double,std::milli>(t2-t1).count(),tf_err=std::max({std::abs(tf_scalar.objective-tf_tiled.objective),std::abs(tf_scalar.alpha_gradient-tf_tiled.alpha_gradient),std::abs(tf_scalar.range_gradient-tf_tiled.range_gradient)});auto clear=[&](){for(const char*n:{"FEDSPATIAL_MIXED_TRACE_TILED_ACTION","FEDSPATIAL_MIXED_CONTRACTIONS_TILED","FEDSPATIAL_THETA_FIRST_TILED","FEDSPATIAL_THETA_HESSIAN_AA_LOG_TILED","FEDSPATIAL_THETA_HESSIAN_AR_LOG_TILED","FEDSPATIAL_THETA_HESSIAN_RR_LOG_TILED","FEDSPATIAL_THETA_HESSIAN_Q_W_TILED"})unsetenv(n);};auto enable=[&](){for(const char*n:{"FEDSPATIAL_MIXED_TRACE_TILED_ACTION","FEDSPATIAL_MIXED_CONTRACTIONS_TILED","FEDSPATIAL_THETA_FIRST_TILED","FEDSPATIAL_THETA_HESSIAN_AA_LOG_TILED","FEDSPATIAL_THETA_HESSIAN_AR_LOG_TILED","FEDSPATIAL_THETA_HESSIAN_RR_LOG_TILED","FEDSPATIAL_THETA_HESSIAN_Q_W_TILED"})setenv(n,"1",1);};clear();const auto p0=std::chrono::steady_clock::now();const auto ps=compute_device_delta_theta_local(c,w,k,p).summary;const auto p1=std::chrono::steady_clock::now();enable();const auto pt=compute_device_delta_theta_local(c,w,k,p).summary;const auto p2=std::chrono::steady_clock::now();double pe=std::abs(ps.objective-pt.objective);for(int i=0;i<3;++i)pe=std::max(pe,std::abs(ps.gradient[i]-pt.gradient[i]));for(int i=0;i<9;++i)pe=std::max(pe,std::abs(ps.hessian[i]-pt.hessian[i]));const double psm=std::chrono::duration<double,std::milli>(p1-p0).count(),ptm=std::chrono::duration<double,std::milli>(p2-p1).count();const auto&r=c.region();std::cout<<"MIXED_TILE_BENCH n=128 m=64 scalar_ms="<<scalar.ms<<" trace_tiled_ms="<<trace.ms<<" full_tiled_ms="<<all.ms<<" trace_speedup="<<scalar.ms/trace.ms<<" full_speedup="<<scalar.ms/all.ms<<" TRACE_MAX_ABS="<<diff(scalar.result,trace.result)<<" FULL_MAX_ABS="<<diff(scalar.result,all.result)<<" ACTION_CALLS="<<r.mixed_action_tile_calls<<" ACTION_RHS="<<r.mixed_action_tile_rhs_columns<<" BI_GEMM_CALLS="<<r.mixed_bi_w2b_gemm_calls<<" V_TZ_TILE_CALLS="<<r.mixed_v_tz_tile_calls<<" V_TZ_RHS="<<r.mixed_v_tz_rhs_columns<<'\n';std::cout<<"THETA_FIRST_TILE_BENCH n=128 m=64 scalar_ms="<<tf_scalar_ms<<" tiled_ms="<<tf_tiled_ms<<" speedup="<<tf_scalar_ms/tf_tiled_ms<<" MAX_ABS="<<tf_err<<" TRACE_TILES="<<r.theta_first_trace_tile_calls<<" TRACE_RHS="<<r.theta_first_trace_rhs_columns<<" T1_GEMMS="<<r.theta_first_t1_gemm_calls<<" T2_TILES="<<r.theta_first_t2_tile_calls<<" T2_RHS="<<r.theta_first_t2_rhs_columns<<'\n';std::cout<<"COMPLETE_DELTA_THETA_BENCH n=128 m=64 scalar_ms="<<psm<<" tiled_ms="<<ptm<<" speedup="<<psm/ptm<<" MAX_ABS="<<pe<<" scalar_solves="<<r.producer_scalar_solve_calls<<" tiled_solves="<<r.producer_tiled_solve_calls<<" tiled_rhs="<<r.producer_tiled_rhs_columns<<'\n';return diff(scalar.result,all.result)<=1e-9&&tf_err<=1e-9&&pe<=1e-8?0:1;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
